func (this *CoolBar) setOrientationOnControl_(orientation int32) {
	this.Composite.setOrientationOnControl_(orientation)
	for row := int32(0); row < int32(len(this.items)); row++ {
		for column := int32(0); column < int32(len(this.items[row])); column++ {
			var item *CoolItem = this.items[row][column]
			if item.arrowImage != (nil) {
				item.arrowImage.impl.dispose_()
				item.arrowImage = nil
			}
			item.UpdateChevron()
		}
	}
}

func (this *CoolBar) WrapItems(maxWidth int32) {
	var itemCount int32 = int32(len(this.originalItems))
	if itemCount < 2 {
		return
	}
	var itemsVisual []*CoolItem = make([]*CoolItem, itemCount)
	var start int32 = 0
	for row := int32(0); row < int32(len(this.items)); row++ {
		copy(itemsVisual[start:], this.items[row][0:0+int32(len(this.items[row]))])
		start += int32(len(this.items[row]))
	}
	var newItems [][]*CoolItem = make([][]*CoolItem, itemCount)
	var rowCount int32 = 0
	var rowWidth int32 = 0
	start = 0
	for i := int32(0); i < itemCount; i++ {
		var item *CoolItem = itemsVisual[i]
		var itemWidth int32 = item.InternalGetMinimumWidth()
		if (i > 0 && item.wrap) || (maxWidth != DEFAULT && rowWidth+itemWidth > maxWidth) {
			if i == start {
				newItems[rowCount] = make([]*CoolItem, 1)
				newItems[rowCount][0] = item
				start = i + 1
				rowWidth = 0
			} else {
				var count int32 = i - start
				newItems[rowCount] = make([]*CoolItem, count)
				copy(newItems[rowCount][0:], itemsVisual[start:start+count])
				start = i
				rowWidth = itemWidth
			}
			rowCount++
		} else {
			rowWidth += itemWidth
		}
	}
	if start < itemCount {
		var count int32 = itemCount - start
		newItems[rowCount] = make([]*CoolItem, count)
		copy(newItems[rowCount][0:], itemsVisual[start:start+count])
		rowCount++
	}
	if int32(len(newItems)) != rowCount {
		var tmp [][]*CoolItem = make([][]*CoolItem, rowCount)
		copy(tmp[0:], newItems[0:0+rowCount])
		this.items = tmp
	} else {
		this.items = newItems
	}
}

func CoolBarCheckStyle(style int32) int32 {
	style |= NO_FOCUS
	return (style | NO_REDRAW_RESIZE) & ^(V_SCROLL | H_SCROLL)
}
